/**
 * Unit tests for MultivariateNormalDistribution#density
 */
public class MultivariateNormalDistribution_density_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDensityWithValidInput() throws Exception {
        // Setup a 2D Multivariate Normal Distribution
        // Means: [0, 0], Covariance: [[1, 0], [0, 1]] (Standard Bivariate Normal)
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test point: [0, 0]
        // Formula: (2 * PI)^(-2/2) * |det|^-0.5 * exp(-0.5 * (0^T * I * 0))
        // = (2 * PI)^-1 * 1^-0.5 * exp(0)
        // = 1 / (2 * PI) approx 0.15915494309
        double[] vals = {0.0, 0.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);

        Assert.assertEquals("Density at mean should be 1/(2*PI) for standard bivariate", expected, actual, EPSILON);

        // Test point: [1, 1]
        // exp(-0.5 * (1^2 + 1^2)) = exp(-1)
        // density = (1 / 2PI) * exp(-1)
        double[] vals2 = {1.0, 1.0};
        double expected2 = (1.0 / (2.0 * Math.PI)) * Math.exp(-1.0);
        double actual2 = distribution.density(vals2);

        Assert.assertEquals("Density at [1,1] should be correctly calculated", expected2, actual2, EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testDensityWithDimensionMismatch() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Dimension is 2, provided array length is 3
        double[] invalidVals = {0.0, 0.0, 0.0};
        distribution.density(invalidVals);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testDensityWithEmptyInputMismatch() throws Exception {
        double[] means = {0.0};
        double[][] covariances = {{1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Dimension is 1, provided array length is 0
        double[] invalidVals = {};
        distribution.density(invalidVals);
    }

    @Test
    public void testDensityOneDimensional() throws Exception {
        // 1D case (Univariate Normal)
        double[] means = {5.0};
        double[][] covariances = {{4.0}}; // std dev = 2
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test at mean: x = 5
        // Formula: (2*PI)^(-1/2) * (4)^(-0.5) * exp(0)
        // = 1 / (sqrt(2*PI) * 2)
        double[] vals = {5.0};
        double expected = 1.0 / (Math.sqrt(2.0 * Math.PI) * 2.0);
        double actual = distribution.density(vals);

        Assert.assertEquals("Density for 1D should match univariate normal formula", expected, actual, EPSILON);
    }
}
